class Router {
  constructor() {
    this.routes = [];
  }
  add(method, path, handler) {
    this.routes.push({ method: String(method).toUpperCase(), path, handler });
  }
  // BUG: 仅按路径前缀匹配，不区分方法，也不解析 :id 参数
  match(method, path) {
    for (const r of this.routes) {
      if (path.startsWith(r.path)) return { handler: r.handler, params: {} };
    }
    return null;
  }
}

module.exports = { Router };

const handlers = {
  listUsers: () => ({ status: 200, body: { users: ['alice', 'bob'] } }),
  getUser: (params) => ({ status: 200, body: { id: params.id } }),
  createUser: (req) => ({ status: 201, body: { created: (req && req.body && req.body.name) || 'unknown' } }),
};

module.exports = handlers;

const { Router } = require('./router');
const h = require('./handlers');

function createApp() {
  const router = new Router();
  router.add('GET', '/users', h.listUsers);
  router.add('GET', '/users/:id', h.getUser);
  router.add('POST', '/users', h.createUser);

  return {
    handle(req) {
      const hit = router.match(req.method, req.path);
      if (!hit) return { status: 404, body: { error: 'not found' } };
      return hit.handler(hit.params, req);
    },
  };
}

module.exports = { createApp };

const assert = require('assert');
const { createApp } = require('./src/index.js');
const app = createApp();

let r = app.handle({ method: 'GET', path: '/users' });
assert.strictEqual(r.status, 200);
assert.deepStrictEqual(r.body.users, ['alice', 'bob']);

r = app.handle({ method: 'GET', path: '/users/42' });
assert.strictEqual(r.status, 200);
assert.deepStrictEqual(r.body, { id: '42' }, '路径参数 :id 必须解析');

r = app.handle({ method: 'POST', path: '/users', body: { name: 'carol' } });
assert.strictEqual(r.status, 201, 'POST /users 不能命中 GET /users');
assert.deepStrictEqual(r.body, { created: 'carol' });

r = app.handle({ method: 'DELETE', path: '/users' });
assert.strictEqual(r.status, 404, '未注册方法应 404');

r = app.handle({ method: 'GET', path: '/orders' });
assert.strictEqual(r.status, 404, '未注册路径应 404');

r = app.handle({ method: 'GET', path: '/users/42/posts' });
assert.strictEqual(r.status, 404, '必须精确匹配，不能前缀命中 /users/:id');

console.log('verify: all pass');

// 并发受限任务池：runPool(tasks, limit, retries)
// BUG: 无并发上限（全部并行）、顺序不保证、错误被吞掉、重试次数未生效
async function runPool(tasks, limit = 2, retries = 1) {
  const results = [];
  await Promise.all(tasks.map(async (task) => {
    let lastErr = null;
    for (let i = 0; i < retries; i++) {
      try { results.push(await task()); lastErr = null; break; }
      catch (e) { lastErr = e; }
    }
    if (lastErr) results.push({ error: lastErr.message });
  }));
  return results;
}

module.exports = { runPool };

const assert = require('assert');
const { runPool } = require('./lib/pool.js');

(async () => {
  let cur = 0;
  let max = 0;
  const mk = (ms) => async () => {
    cur += 1; max = Math.max(max, cur);
    try { await new Promise((r) => setTimeout(r, ms)); return ms; }
    finally { cur -= 1; }
  };
  const res = await runPool([mk(30), mk(20), mk(10), mk(5), mk(1)], 2, 1);
  assert.strictEqual(res.length, 5, '返回结果数量应与任务一致');
  assert.ok(max <= 2, `并发上限应为 2，实际峰值 ${max}`);
  assert.ok(res.every((r) => r && r.ok === true), '所有任务应成功');
  assert.deepStrictEqual(res.map((r) => r.value), [30, 20, 10, 5, 1], '结果顺序必须与任务顺序一致');

  let attempts = 0;
  const flaky = async () => { attempts += 1; if (attempts < 2) throw new Error('boom'); return 'ok'; };
  const r2 = await runPool([flaky], 1, 1);
  assert.strictEqual(r2[0].ok, true, '重试后应成功');
  assert.strictEqual(r2[0].value, 'ok');
  assert.strictEqual(attempts, 2, 'retries=1 应共尝试 2 次');

  let tries = 0;
  const dead = async () => { tries += 1; throw new Error('dead'); };
  const r3 = await runPool([dead], 1, 2);
  assert.strictEqual(r3[0].ok, false, '重试耗尽应标记失败');
  assert.strictEqual(tries, 3, 'retries=2 应共尝试 3 次');
  assert.match(String(r3[0].error), /dead/, '失败结果应保留错误信息');

  const mixed = await runPool([async () => 1, dead, async () => 3], 2, 0);
  assert.deepStrictEqual(mixed.map((r) => r.ok), [true, false, true], '单个任务失败不应中断其他任务');

  console.log('verify: all pass');
  process.exit(0);
})().catch((e) => { console.error(e.message); process.exit(1); });

// 用户校验：返回错误信息数组，空数组表示合法
function validateUser(u) {
  const errors = [];
  if (!u || typeof u !== 'object') return ['invalid user'];

  const name = String(u.name || '').trim();
  if (name.length < 2) errors.push('name too short');

  // BUG: 邮箱校验过松，'not-an-email' 这类非法值被放过
  if (!String(u.email || '').includes('@')) return errors;
  if (!/^[^@\s]+@[^@\s]+\.[a-z]+$/.test(String(u.email))) errors.push('invalid email');

  // BUG: 用真值判断，age 为 0（合法值）被当成未提供
  if (!u.age) errors.push('age required');
  else if (u.age < 0 || u.age > 150) errors.push('age out of range');

  return errors;
}

module.exports = { validateUser };

const { validateUser } = require('./validator');

// 对外组合接口：校验 + 归一化（行为由 validator 决定）
function normalizeUser(u) {
  const errors = validateUser(u);
  if (errors.length) return { ok: false, errors };
  return {
    ok: true,
    user: { name: String(u.name).trim(), email: String(u.email).toLowerCase(), age: Number(u.age) },
  };
}

module.exports = { normalizeUser };

const { validateUser } = require('../lib/validator.js');

module.exports = [
  { name: '合法用户通过', run: () => validateUser({ name: '张三', email: 'a@b.com', age: 30 }), expect: [] },
  { name: '姓名过短', run: () => validateUser({ name: 'a', email: 'a@b.com', age: 30 }), expect: ['name too short'] },
  { name: '非法邮箱应报错', run: () => validateUser({ name: '张三', email: 'not-an-email', age: 30 }), expect: ['invalid email'] },
  { name: 'age 为 0 是合法值', run: () => validateUser({ name: '张三', email: 'a@b.com', age: 0 }), expect: [] },
  { name: 'age 越界', run: () => validateUser({ name: '张三', email: 'a@b.com', age: 200 }), expect: ['age out of range'] },
  { name: '非对象拒绝', run: () => validateUser(null), expect: ['invalid user'] },
];

// 迷你测试套件：只读地执行 cases.js 中的用例，不做任何跳过处理
const assert = require('assert');
const cases = require('./cases.js');

let failed = 0;
for (const c of cases) {
  try {
    assert.deepStrictEqual(c.run(), c.expect);
  } catch (e) {
    failed += 1;
    console.error(`FAIL ${c.name}: ${e.message}`);
  }
}

if (failed) { console.error(`${failed}/${cases.length} 个用例失败`); process.exit(1); }
console.log('verify: all pass');

// 订单校验（与 users.js 中的规则重复，需提取共享）
function validateOrder(o) {
  const errs = [];
  if (!o || typeof o !== 'object') return ['invalid order'];
  if (!o.id || String(o.id).length < 3) errs.push('id too short');
  if (!(Number(o.amount) > 0)) errs.push('amount must be positive');
  if (o.currency && !['CNY', 'USD'].includes(o.currency)) errs.push('unsupported currency');
  return errs;
}

function totalOf(orders) {
  return orders
    .filter((o) => validateOrder(o).length === 0)
    .reduce((a, o) => a + Number(o.amount), 0);
}

module.exports = { validateOrder, totalOf };

// 用户账户校验（与 orders.js 中的规则重复，需提取共享）
function validateAccount(a) {
  const errs = [];
  if (!a || typeof a !== 'object') return ['invalid account'];
  if (!a.id || String(a.id).length < 3) errs.push('id too short');
  if (!(Number(a.amount) > 0)) errs.push('amount must be positive');
  if (a.currency && !['CNY', 'USD'].includes(a.currency)) errs.push('unsupported currency');
  return errs;
}

function activeBalance(accounts) {
  return accounts
    .filter((a) => validateAccount(a).length === 0)
    .reduce((s, a) => s + Number(a.amount), 0);
}

module.exports = { validateAccount, activeBalance };

const assert = require('assert');
const fs = require('fs');
const { validateOrder, totalOf } = require('./lib/orders.js');
const { validateAccount, activeBalance } = require('./lib/users.js');
const shared = require('./lib/validate.js');

// 行为不变（重构前基准）
assert.deepStrictEqual(validateOrder({ id: 'a1', amount: 5 }), ['id too short']);
assert.deepStrictEqual(validateOrder({ id: 'abc', amount: -1 }), ['amount must be positive']);
assert.deepStrictEqual(validateOrder({ id: 'abc', amount: 5, currency: 'JPY' }), ['unsupported currency']);
assert.deepStrictEqual(validateOrder({ id: 'abc', amount: 5, currency: 'CNY' }), []);
assert.deepStrictEqual(validateOrder(null), ['invalid order']);
assert.strictEqual(totalOf([{ id: 'abc', amount: 10 }, { id: 'x', amount: 5 }, { id: 'abcd', amount: 2.5 }]), 12.5);

assert.deepStrictEqual(validateAccount({ id: 'a1', amount: 5 }), ['id too short']);
assert.deepStrictEqual(validateAccount({ id: 'abc', amount: 0 }), ['amount must be positive']);
assert.deepStrictEqual(validateAccount({ id: 'abc', amount: 5, currency: 'USD' }), []);
assert.strictEqual(activeBalance([{ id: 'abc', amount: 7 }, { id: 'zz', amount: 3 }]), 7);

// 重构目标：共享模块存在且被两处引用
assert.strictEqual(typeof shared.validateCommon, 'function', 'lib/validate.js 必须导出 validateCommon');
assert.deepStrictEqual(shared.validateCommon({ id: 'abc', amount: 5 }), []);
assert.deepStrictEqual(shared.validateCommon({ id: 'a', amount: -2 }), ['id too short', 'amount must be positive']);

const ordersSrc = fs.readFileSync('./lib/orders.js', 'utf8');
const usersSrc = fs.readFileSync('./lib/users.js', 'utf8');
assert.ok(/validate\.js/.test(ordersSrc), 'orders.js 应引用共享模块');
assert.ok(/validate\.js/.test(usersSrc), 'users.js 应引用共享模块');

const dupId = (ordersSrc.match(/length < 3/g) || []).length + (usersSrc.match(/length < 3/g) || []).length;
assert.strictEqual(dupId, 0, 'id 长度规则不得再内联出现（应收敛到共享模块）');
const dupCurrency = (ordersSrc.match(/'CNY'/g) || []).length + (usersSrc.match(/'CNY'/g) || []).length;
assert.ok(dupCurrency <= 1, `货币白名单应只保留一处，发现 ${dupCurrency} 处`);

console.log('verify: all pass');

const RATES = { CNY: 1, USD: 7.2, EUR: 7.8 }; // 折算到 CNY 的系数

function toCny(amount, from) {
  const rate = RATES[from];
  if (!rate) throw new Error('unsupported currency: ' + from);
  return Number(amount) * rate;
}

function fromCny(amount, to) {
  const rate = RATES[to];
  if (!rate) throw new Error('unsupported currency: ' + to);
  return Number(amount) / rate;
}

module.exports = { toCny, fromCny, RATES };

// 折扣：满 100 CNY 减 10，VIP 额外 5%（折扣基于折前金额）
function applyDiscount(amountCny, isVip) {
  let out = Number(amountCny);
  if (out >= 100) out -= 10;
  if (isVip) out *= 0.95;
  return out;
}

module.exports = { applyDiscount };

// 税率 6%，仅对折后金额计税
function applyTax(amountCny, rate = 0.06) {
  return Number(amountCny) * (1 + rate);
}

module.exports = { applyTax };

// 组装发票明细：四舍五入到分
function buildLine(item, amountCny) {
  return {
    sku: item.sku,
    qty: item.qty,
    amount: Math.round(amountCny * 100) / 100,
  };
}

module.exports = { buildLine };

const { toCny } = require('./currency');
const { applyDiscount } = require('./discount');
const { applyTax } = require('./tax');
const { buildLine } = require('./invoice');

// 端到端报价：换算 → 折扣 → 计税 → 明细
function quote(order) {
  const items = Array.isArray(order.items) ? order.items : [];
  let subtotal = 0;
  for (const it of items) {
    subtotal += toCny(Number(it.price) * Number(it.qty), it.currency || 'CNY');
  }
  const discounted = applyDiscount(subtotal, !!order.isVip);
  // BUG: 折扣被重复应用了一次（应在折后金额上计税，而不是再折一次）
  const taxed = applyDiscount(discounted, !!order.isVip);
  const total = applyTax(taxed);
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    total: Math.round(total * 100) / 100,
    lines: items.map((it) => buildLine(it, toCny(Number(it.price) * Number(it.qty), it.currency || 'CNY'))),
  };
}

module.exports = { quote };

const assert = require('assert');
const { quote } = require('./src/pipeline.js');

// 场景 1：普通用户，200 CNY 单品 → 满减 10 → 190 → 税 6% → 201.4
let q = quote({ items: [{ sku: 'A', qty: 2, price: 100, currency: 'CNY' }] });
assert.strictEqual(q.subtotal, 200);
assert.strictEqual(q.total, 201.4, `场景1 期望 201.4，实际 ${q.total}`);

// 场景 2：VIP 用户，200 CNY → 满减 10 → 190 → VIP 95% → 180.5 → 税 6% → 191.33
q = quote({ isVip: true, items: [{ sku: 'A', qty: 2, price: 100, currency: 'CNY' }] });
assert.strictEqual(q.total, 191.33, `场景2 期望 191.33，实际 ${q.total}`);

// 场景 3：外币换算，10 USD × 3 件 = 30 USD = 216 CNY → 满减 10 → 206 → 税 6% → 218.36
q = quote({ items: [{ sku: 'B', qty: 3, price: 10, currency: 'USD' }] });
assert.strictEqual(q.subtotal, 216);
assert.strictEqual(q.total, 218.36, `场景3 期望 218.36，实际 ${q.total}`);
assert.deepStrictEqual(q.lines, [{ sku: 'B', qty: 3, amount: 216 }], '明细金额应为折算后的 CNY');

// 场景 4：不满 100 无满减
q = quote({ items: [{ sku: 'C', qty: 1, price: 50, currency: 'CNY' }] });
assert.strictEqual(q.total, 53, `场景4 期望 53，实际 ${q.total}`);

console.log('verify: all pass');
